#!/usr/bin/env bash
set -euo pipefail

# Generates the « SOE Test » launcher icons: the production design with a red « TEST » band.
#
# Run it after `dart run flutter_launcher_icons` (which only knows the production icon):
#   dart run flutter_launcher_icons && ./scripts/generate_test_icons.sh
#
# Inputs : assets/icon/app_icon.png (full square), assets/icon/app_icon_foreground.png (adaptive
#          foreground, transparent), and the production icons generated by flutter_launcher_icons.
# Outputs: assets/icon/app_icon_test*.png, Android mipmap ic_launcher_test (+ adaptive xml and
#          foreground), iOS AppIconTest.appiconset. Each test file has the size of its production
#          counterpart. Requires ImageMagick 7 (`magick`).

cd "$(dirname "$0")/.."

command -v magick >/dev/null || { echo "Error: ImageMagick (magick) is required." >&2; exit 1; }

FONT="assets/fonts/Figtree-ExtraBold.ttf"
BAND="#D92D20"
FULL="assets/icon/app_icon.png"
FOREGROUND="assets/icon/app_icon_foreground.png"
FULL_TEST="assets/icon/app_icon_test.png"
FOREGROUND_TEST="assets/icon/app_icon_test_foreground.png"
RES="android/app/src/main/res"
IOS_PROD="ios/Runner/Assets.xcassets/AppIcon.appiconset"
IOS_TEST="ios/Runner/Assets.xcassets/AppIconTest.appiconset"

# ── 1024 px sources (coordinates for a 1024 x 1024 canvas) ──
# Full icon: band across the lower part, under the bulb; no alpha (App Store rule).
magick "$FULL" -resize 1024x1024 \
  -fill "$BAND" -draw 'rectangle 0,716 1024,860' \
  -font "$FONT" -pointsize 120 -fill white -gravity center -annotate +0+268 'TEST' \
  -alpha off "$FULL_TEST"
# Adaptive foreground: band kept inside the launcher safe zone (the mask clips its ends).
magick "$FOREGROUND" -resize 1024x1024 \
  -fill "$BAND" -draw 'rectangle 0,700 1024,828' \
  -font "$FONT" -pointsize 110 -fill white -gravity center -annotate +0+246 'TEST' \
  "$FOREGROUND_TEST"

# Resizes $1 to the size of the existing file $2 and writes $3 (extra magick options after).
resize_like() {
  local source="$1" model="$2" target="$3"
  shift 3
  local size
  size=$(magick identify -format '%wx%h' "$model")
  magick "$source" -resize "${size}!" "$@" "$target"
}

# ── Android ──
for dir in "$RES"/mipmap-*dpi; do
  [ -f "$dir/ic_launcher.png" ] && resize_like "$FULL_TEST" "$dir/ic_launcher.png" "$dir/ic_launcher_test.png"
done
for dir in "$RES"/drawable-*dpi; do
  [ -f "$dir/ic_launcher_foreground.png" ] &&
    resize_like "$FOREGROUND_TEST" "$dir/ic_launcher_foreground.png" "$dir/ic_launcher_test_foreground.png"
done
sed 's#@drawable/ic_launcher_foreground#@drawable/ic_launcher_test_foreground#' \
  "$RES/mipmap-anydpi-v26/ic_launcher.xml" > "$RES/mipmap-anydpi-v26/ic_launcher_test.xml"

# flutter_launcher_icons rewrites android:icon to @mipmap/ic_launcher: restore the placeholder
# that android/app/build.gradle.kts fills (ic_launcher or ic_launcher_test).
sed -i.bak 's#android:icon="@mipmap/ic_launcher"#android:icon="${appIcon}"#' \
  android/app/src/main/AndroidManifest.xml
rm -f android/app/src/main/AndroidManifest.xml.bak

# ── iOS ──
# Same for the Xcode project: the icon set comes from APP_ICON_NAME (ios/Flutter/AppIdentity.xcconfig).
sed -i.bak 's#ASSETCATALOG_COMPILER_APPICON_NAME = AppIcon;#ASSETCATALOG_COMPILER_APPICON_NAME = "$(APP_ICON_NAME)";#' \
  ios/Runner.xcodeproj/project.pbxproj
rm -f ios/Runner.xcodeproj/project.pbxproj.bak
rm -rf "$IOS_TEST"
mkdir -p "$IOS_TEST"
cp "$IOS_PROD/Contents.json" "$IOS_TEST/Contents.json"
for png in "$IOS_PROD"/*.png; do
  resize_like "$FULL_TEST" "$png" "$IOS_TEST/$(basename "$png")" -alpha off
done

echo "SOE Test icons generated (Android ic_launcher_test, iOS AppIconTest)."
